def transform(grid):
    h,w=len(grid),len(grid[0]); from collections import Counter,deque
    counts=Counter(x for row in grid for x in row); bg=counts.most_common(1)[0][0]
    fg=[x for x in counts if x!=bg][0]
    out=[row[:] for row in grid]
    # Label the original 4-connected foreground components.
    comp=[[-1]*w for _ in range(h)]; label=0
    for r in range(h):
      for c in range(w):
       if grid[r][c]!=fg or comp[r][c]>=0: continue
       q=deque([(r,c)]); comp[r][c]=label
       while q:
        y,x=q.popleft()
        for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
         if 0<=yy<h and 0<=xx<w and grid[yy][xx]==fg and comp[yy][xx]<0:
          comp[yy][xx]=label; q.append((yy,xx))
       label+=1
    for r in range(h):
      cs=[c for c in range(w) if grid[r][c]==fg]
      for a,b in zip(cs,cs[1:]):
       if comp[r][a]!=comp[r][b]:
        for c in range(a+1,b):
         if grid[r][c]==bg: out[r][c]=2
    for c in range(w):
      rs=[r for r in range(h) if grid[r][c]==fg]
      for a,b in zip(rs,rs[1:]):
       if comp[a][c]!=comp[b][c]:
        for r in range(a+1,b):
         if grid[r][c]==bg: out[r][c]=2
    return out
